public class JSumDigits {
	public static void main(String[] args) {
		//Paso 1: Definir las variables que necesitamos para este programa
		int num = 1234;
		int lastDigit;
		int total = 0;
		//Paso 2: Sumar los digitos del entero
		do {
			//Paso 2.1: Obtener el ultimo digito del entero
			lastDigit = num % 10;
			//Paso 2.2: Agregar el ultimo digito a la suma de digitos hasta ahora
			total = total + lastDigit;
			//Paso 2.3: Eliminar el ultimo digito del entero
			num = num / 10;
			System.out.println("ultimo digito: "+lastDigit+", suma: "+total+", entero: "+num);
		} while (num > 0);
		System.out.println("La suma de los digitos: " + total);
	}
}

